import {getDb,closeDb} from './db/init.ts';
import {findSharedDonors} from './db/queries.ts';
const c=await getDb();
const q=async s=>(await (await c.run(s)).getRowObjects());
const j=v=>JSON.stringify(v,(_,x)=>typeof x==='bigint'?x.toString():x);
console.log('MEMBER', j(await q("SELECT member_id,fec_candidate_id,state,role,in_office FROM members WHERE bioguide_id='G000608'")));
console.log('IE', j(await q("SELECT * FROM super_pac_ie WHERE member_id='darline-graham'")));
console.log('DONOR_SRC', j(await q("SELECT source, count(*) n, sum(amount) total FROM donors WHERE member_id='darline-graham' GROUP BY 1")));
console.log('PFD', j(await q("SELECT count(*) n FROM pfd_transactions WHERE member_id='darline-graham'")));
console.log('BILLS', j(await q("SELECT sponsor_role, count(*) n FROM bills WHERE member_id='darline-graham' GROUP BY 1")));
console.log('SHARED_REAL', j(await findSharedDonors('darline-graham')));
closeDb();
